param([string]$SupportPath=(Join-Path $PSScriptRoot '../Installer/Support.ps1'),[string]$FixtureRoot=([IO.Path]::GetTempPath()))
$ErrorActionPreference='Stop'
. $SupportPath
$script:ExpectedGame=@{'Star Renegades.exe'='';'Star Renegades_Data/Managed/Assembly-CSharp.dll'='';'Star Renegades_Data/data.unity3d'=''}
$script:SkipProcessForFixtures=$true
$base=Join-Path ([IO.Path]::GetFullPath($FixtureRoot)) ('SRBugfix-tests-'+[Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $base | Out-Null
$passed=0;$failed=0
function Assert($condition,$message){if(-not $condition){throw $message}}
function Fixture([string]$Profile='SRBugfix') {
 $root=Join-Path $base ([Guid]::NewGuid().ToString('N')+' game with spaces');$payload=Join-Path $base ([Guid]::NewGuid().ToString('N')+' package')
 foreach($relative in @($script:ExpectedGame.Keys)){$path=Join-Path $root $relative;[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($path))|Out-Null;[IO.File]::WriteAllText($path,$relative);$script:ExpectedGame[$relative]=(Get-FileHash $path).Hash.ToLowerInvariant()}
 $files=@{}
 $paths=if($Profile -eq 'SRBugfix'){@('winhttp.dll','doorstop_config.ini','SRBugfix/SRBugfix.dll','SRBugfix/0Harmony.dll','SRBugfix/fixes.json')}else{@('winhttp.dll','doorstop_config.ini','SRRebalance/SRRebalance.dll','SRRebalance/0Harmony.dll','SRRebalance/fixes.json','SRRebalance/rebalance.json')}
 foreach($relative in $paths){$path=Join-Path $payload $relative;[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($path))|Out-Null;[IO.File]::WriteAllText($path,$relative);$files[$relative]=(Get-FileHash $path).Hash.ToLowerInvariant()}
 $package=@{format=1;version='0.1.0';files=$files};if($Profile -eq 'SRRebalance'){$package.id=$Profile};$package|ConvertTo-Json -Depth 10|Set-Content (Join-Path $payload 'package.json')
 return @{root=$root;payload=$payload}
}
function Test($name,[scriptblock]$body){try{& $body;$script:passed++;Write-Host "PASS $name"}catch{$script:failed++;Write-Host "FAIL ${name}: $($_.Exception.Message)"}}
function Reject([scriptblock]$body){$rejected=$false;try{& $body}catch{$rejected=$true};Assert $rejected 'Expected refusal'}
Test 'FreshInstallUninstall' {$f=Fixture;Install-SRBugfix $f.root $f.payload;Assert (Test-Path (Join-Path $f.root 'SRBugfix/receipt.json')) 'Missing receipt';Uninstall-SRBugfix $f.root;Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Loader retained';Assert (-not(Test-Path (Join-Path $f.root 'SRBugfix/receipt.json'))) 'Receipt retained'}
Test 'RepeatAndUpgradePreserveBaseline' {$f=Fixture;Install-SRBugfix $f.root $f.payload;Install-SRBugfix $f.root $f.payload;[IO.File]::WriteAllText((Join-Path $f.payload 'SRBugfix/SRBugfix.dll'),'upgrade');$p=Get-Content (Join-Path $f.payload 'package.json') -Raw|ConvertFrom-Json;$p.files.'SRBugfix/SRBugfix.dll'=(Get-FileHash (Join-Path $f.payload 'SRBugfix/SRBugfix.dll')).Hash.ToLowerInvariant();$p.version='0.1.1';$p|ConvertTo-Json -Depth 10|Set-Content (Join-Path $f.payload 'package.json');Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root;Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Upgrade changed original baseline'}
Test 'ForeignLoadersRefused' {foreach($name in @('winhttp.dll','doorstop_config.ini','BepInEx','SRRebalance','SRBugfix')){$f=Fixture;[IO.File]::WriteAllText((Join-Path $f.root $name),'foreign');Reject {Install-SRBugfix $f.root $f.payload};Assert ([IO.File]::ReadAllText((Join-Path $f.root $name)) -eq 'foreign') 'Foreign file touched'}}
Test 'ModifiedOwnedFilePreserved' {$f=Fixture;Install-SRBugfix $f.root $f.payload;$p=Join-Path $f.root 'doorstop_config.ini';[IO.File]::WriteAllText($p,'custom');Reject {Uninstall-SRBugfix $f.root};Assert ([IO.File]::ReadAllText($p) -eq 'custom') 'Edited file removed';Reject {Install-SRBugfix $f.root $f.payload}}
Test 'WrongPackageOrGameHashRefusedBeforeWrites' {foreach($kind in @('package','game')){$f=Fixture;$p=if($kind -eq 'package'){Join-Path $f.payload 'SRBugfix/fixes.json'}else{Join-Path $f.root 'Star Renegades_Data/data.unity3d'};[IO.File]::WriteAllText($p,'wrong');Reject {Install-SRBugfix $f.root $f.payload};Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Partial installation'}}
Test 'PayloadTraversalRejected' {$f=Fixture;$p=Get-Content (Join-Path $f.payload 'package.json') -Raw|ConvertFrom-Json;$p.files|Add-Member NoteProperty '../escape.dll' ('0'*64);$p|ConvertTo-Json -Depth 10|Set-Content (Join-Path $f.payload 'package.json');Reject {Install-SRBugfix $f.root $f.payload};Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Traversal wrote files'}
Test 'CopyFailureRollsBack' {$f=Fixture;$script:WriteInjection={param($path,$bytes,$relative) if($relative -eq 'SRBugfix/0Harmony.dll'){throw 'Injected copy failure'};[IO.File]::WriteAllBytes($path,$bytes)};try{Reject {Install-SRBugfix $f.root $f.payload}}finally{$script:WriteInjection=$null};Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Copy failure left loader';Assert (-not(Test-Path (Join-Path $f.root 'SRBugfix/receipt.json'))) 'Copy failure left receipt'}
Test 'InterruptedInstallRecovers' {$f=Fixture;$script:InterruptForFixtures=2;try{Reject {Install-SRBugfix $f.root $f.payload}}finally{$script:InterruptForFixtures=0};Assert (Test-Path (Join-Path $f.root '.SRBugfix-transaction/journal.json')) 'No recovery journal';Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root;Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Recovery lost baseline'}
Test 'InterruptedUninstallRecovers' {$f=Fixture;Install-SRBugfix $f.root $f.payload;$script:InterruptForFixtures=2;try{Reject {Uninstall-SRBugfix $f.root}}finally{$script:InterruptForFixtures=0};Uninstall-SRBugfix $f.root;Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Uninstall recovery failed'}
Test 'RunningGameRefused' {$f=Fixture;$script:ProcessInjection={param($root) $true};try{Reject {Install-SRBugfix $f.root $f.payload}}finally{$script:ProcessInjection=$null};Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Running game modified'}
Test 'ReinstallAfterUninstallWithLog' {$f=Fixture;Install-SRBugfix $f.root $f.payload;[IO.File]::WriteAllText((Join-Path $f.root 'SRBugfix/bugfix.log'),'log');Uninstall-SRBugfix $f.root;Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root;Assert ([IO.File]::ReadAllText((Join-Path $f.root 'SRBugfix/bugfix.log')) -eq 'log') 'Log was removed'}
Test 'SecondarySteamLibraryWithSpaces' {$f=Fixture;$steam=Join-Path $base 'Steam root';$lib=Join-Path $base 'Secondary library';$game=Join-Path $lib 'steamapps/common/Star Renegades';[IO.Directory]::CreateDirectory((Join-Path $steam 'steamapps'))|Out-Null;[IO.Directory]::CreateDirectory($game)|Out-Null;[IO.File]::WriteAllText((Join-Path $game 'Star Renegades.exe'),'fixture');[IO.File]::WriteAllText((Join-Path $steam 'steamapps/libraryfolders.vdf'),('"libraryfolders" { "0" { "path" "'+$lib.Replace('\','\\')+'" } }'));[IO.File]::WriteAllText((Join-Path $lib 'steamapps/appmanifest_651670.acf'),'"AppState" { "installdir" "Star Renegades" }');$found=@(Find-SRGame @($steam));Assert ($found.Count -eq 1 -and $found[0] -eq $game) 'Secondary Steam path missed'}
Test 'JunctionRootRefused' {$f=Fixture;$link=Join-Path $base ([Guid]::NewGuid().ToString('N')+' junction');New-Item -ItemType Junction -Path $link -Target $f.root|Out-Null;Reject {Install-SRBugfix $link $f.payload};Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Junction followed'}
Test 'RecoveryPreservesEditedPartialFile' {$f=Fixture;$script:InterruptForFixtures=2;try{Reject {Install-SRBugfix $f.root $f.payload}}finally{$script:InterruptForFixtures=0};$path=Join-Path $f.root 'winhttp.dll';[IO.File]::WriteAllText($path,'edited after interruption');Reject {Install-SRBugfix $f.root $f.payload};Assert ([IO.File]::ReadAllText($path) -eq 'edited after interruption') 'Recovery overwrote an edit'}
Test 'InterruptedPayloadWriteRecovers' {$f=Fixture;$script:InterruptForFixtures=-1;$script:WriteInjection={param($path,$bytes) [IO.File]::WriteAllBytes($path,[byte[]]$bytes[0..3]);throw 'Fixture mid-write interrupt'};try{Reject {Install-SRBugfix $f.root $f.payload}}finally{$script:WriteInjection=$null;$script:InterruptForFixtures=0};Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root;Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Interrupted write recovery failed'}
Test 'UnpublishedJournalAndCleanupInterruptionRecover' {foreach($state in @('empty','unpublished')){$f=Fixture;$dir=Join-Path $f.root '.SRBugfix-transaction';[IO.Directory]::CreateDirectory($dir)|Out-Null;if($state -eq 'unpublished'){[IO.File]::WriteAllText((Join-Path $dir 'journal.json.new'),'partial journal')};Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root;Assert (-not(Test-Path $dir)) 'Lifecycle residue not recovered'}}
Test 'UnknownTransactionResiduePreserved' {$f=Fixture;$dir=Join-Path $f.root '.SRBugfix-transaction';[IO.Directory]::CreateDirectory($dir)|Out-Null;[IO.File]::WriteAllText((Join-Path $dir 'unknown.txt'),'preserve');Reject {Install-SRBugfix $f.root $f.payload};Assert (Test-Path (Join-Path $dir 'unknown.txt')) 'Unowned transaction residue removed'}
Test 'InterruptedRestoreStageRecovers' {$f=Fixture;Install-SRBugfix $f.root $f.payload;$script:InterruptForFixtures=2;try{Reject {Uninstall-SRBugfix $f.root}}finally{$script:InterruptForFixtures=0};[IO.File]::WriteAllBytes((Join-Path $f.root '.SRBugfix-transaction/restore-0.bin'),[byte[]]@(1,2,3));Uninstall-SRBugfix $f.root;Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Partial rollback stage blocked recovery'}
. $SupportPath -ModId SRRebalance
$script:ExpectedGame=@{'Star Renegades.exe'='';'Star Renegades_Data/Managed/Assembly-CSharp.dll'='';'Star Renegades_Data/data.unity3d'=''}
$script:SkipProcessForFixtures=$true
Test 'RebalanceStandaloneInstallUpdateUninstallKeepsSavesAndLogs' {
 $f=Fixture 'SRRebalance';$save=Join-Path $f.root 'saves/player.sav';[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($save))|Out-Null;[IO.File]::WriteAllText($save,'save');Install-SRBugfix $f.root $f.payload
 $receipt=Read-SRJson (Join-Path $f.root 'SRRebalance/receipt.json');Assert ($receipt.id -eq 'SRRebalance' -and $receipt.files.Count -eq 6) 'Wrong Rebalance receipt';Assert (Test-Path (Join-Path $f.root 'SRRebalance/rebalance.json')) 'Rebalance configuration missing';Assert (-not(Test-Path (Join-Path $f.root 'SRBugfix/receipt.json'))) 'Bugfix receipt created'
 $log=Join-Path $f.root 'SRRebalance/rebalance.log';[IO.File]::WriteAllText($log,'log');[IO.File]::WriteAllText((Join-Path $f.payload 'SRRebalance/rebalance.json'),'upgrade');$p=Read-SRJson (Join-Path $f.payload 'package.json');$p.files.'SRRebalance/rebalance.json'=(Get-FileHash (Join-Path $f.payload 'SRRebalance/rebalance.json')).Hash.ToLowerInvariant();$p.version='0.1.1';$p|ConvertTo-Json -Depth 10|Set-Content (Join-Path $f.payload 'package.json');Install-SRBugfix $f.root $f.payload
 Assert ([IO.File]::ReadAllText((Join-Path $f.root 'SRRebalance/rebalance.json')) -eq 'upgrade') 'Upgrade not applied';Uninstall-SRBugfix $f.root
 foreach($path in @('winhttp.dll','doorstop_config.ini','SRRebalance/SRRebalance.dll','SRRebalance/0Harmony.dll','SRRebalance/fixes.json','SRRebalance/rebalance.json','SRRebalance/receipt.json')){Assert (-not(Test-Path (Join-Path $f.root $path))) "Owned file retained: $path"};Assert ([IO.File]::ReadAllText($save) -eq 'save') 'Save changed';Assert ([IO.File]::ReadAllText($log) -eq 'log') 'Log changed'
}
Test 'RebalanceInterruptedSixthAndReceiptWritesRecover' {foreach($index in @(6,7)){$f=Fixture 'SRRebalance';$script:InterruptForFixtures=$index;try{Reject {Install-SRBugfix $f.root $f.payload}}finally{$script:InterruptForFixtures=0};Assert (Test-Path (Join-Path $f.root '.SRRebalance-transaction/journal.json')) 'Missing Rebalance journal';Assert (-not(Test-Path (Join-Path $f.root '.SRBugfix-transaction'))) 'Wrong transaction profile';Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root;Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Recovered install retained loader';Assert (-not(Test-Path (Join-Path $f.root '.SRRebalance-transaction'))) 'Journal not cleared'}}
Test 'RebalanceInterruptedUninstallRecovers' {$f=Fixture 'SRRebalance';Install-SRBugfix $f.root $f.payload;$script:InterruptForFixtures=6;try{Reject {Uninstall-SRBugfix $f.root}}finally{$script:InterruptForFixtures=0};[IO.File]::WriteAllBytes((Join-Path $f.root '.SRRebalance-transaction/restore-6.bin'),[byte[]]@(1,2));Uninstall-SRBugfix $f.root;Assert (-not(Test-Path (Join-Path $f.root 'SRRebalance/receipt.json'))) 'Uninstall recovery retained receipt'}
Test 'RebalanceCopyFailureRollsBackAllSixFiles' {$f=Fixture 'SRRebalance';$script:WriteInjection={param($path,$bytes,$relative) if($relative -eq 'SRRebalance/rebalance.json'){throw 'Injected sixth-file copy failure'};[IO.File]::WriteAllBytes($path,$bytes)};try{Reject {Install-SRBugfix $f.root $f.payload}}finally{$script:WriteInjection=$null};Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Failed installation retained loader';Assert (-not(Test-Path (Join-Path $f.root 'SRRebalance/receipt.json'))) 'Failed installation retained receipt';Assert (-not(Test-Path (Join-Path $f.root '.SRRebalance-transaction'))) 'Failed installation retained journal'}
Test 'RebalanceEditedConfigurationPreservedDuringUpdateUninstallRecovery' {foreach($phase in @('installed','interrupted')){$f=Fixture 'SRRebalance';if($phase -eq 'interrupted'){$script:InterruptForFixtures=6;try{Reject {Install-SRBugfix $f.root $f.payload}}finally{$script:InterruptForFixtures=0}}else{Install-SRBugfix $f.root $f.payload};$path=Join-Path $f.root 'SRRebalance/rebalance.json';[IO.File]::WriteAllText($path,'personal config');Reject {Install-SRBugfix $f.root $f.payload};Reject {Uninstall-SRBugfix $f.root};Assert ([IO.File]::ReadAllText($path) -eq 'personal config') 'Edited configuration overwritten'}}
Test 'RebalanceHashMismatchRefused' {$f=Fixture 'SRRebalance';[IO.File]::WriteAllText((Join-Path $f.payload 'SRRebalance/rebalance.json'),'bad');Reject {Install-SRBugfix $f.root $f.payload};Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Bad configuration hash installed'}
Test 'RebalanceForeignModsRefusedOnFreshAndExistingInstall' {foreach($phase in @('fresh','update')){foreach($relative in @('BepInEx/foreign.dll','SRBugfix/SRBugfix.dll')){$f=Fixture 'SRRebalance';if($phase -eq 'update'){Install-SRBugfix $f.root $f.payload};$path=Join-Path $f.root $relative;[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($path))|Out-Null;[IO.File]::WriteAllText($path,'foreign');Reject {Install-SRBugfix $f.root $f.payload};Assert ([IO.File]::ReadAllText($path) -eq 'foreign') 'Foreign mod altered'}}}
Test 'RebalanceAllowsBothInertLogFolders' {$f=Fixture 'SRRebalance';foreach($pair in @(@('SRBugfix','bugfix.log'),@('SRRebalance','rebalance.log'))){$dir=Join-Path $f.root $pair[0];[IO.Directory]::CreateDirectory($dir)|Out-Null;[IO.File]::WriteAllText((Join-Path $dir $pair[1]),'kept log')};Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root;Assert ([IO.File]::ReadAllText((Join-Path $f.root 'SRBugfix/bugfix.log')) -eq 'kept log') 'Other log removed'}
Test 'RebalanceRejectsUnknownTransactionIndex' {$f=Fixture 'SRRebalance';$dir=Join-Path $f.root '.SRRebalance-transaction';[IO.Directory]::CreateDirectory($dir)|Out-Null;[IO.File]::WriteAllText((Join-Path $dir 'stage-7.bin'),'preserve');Reject {Install-SRBugfix $f.root $f.payload};Assert (Test-Path (Join-Path $dir 'stage-7.bin')) 'Out-of-range stage removed'}
Test 'RebalanceRejectsMismatchedOrUnknownPackageId' {foreach($id in @('SRBugfix','Unknown')){$f=Fixture 'SRRebalance';$p=Read-SRJson (Join-Path $f.payload 'package.json');$p.id=$id;$p|ConvertTo-Json -Depth 10|Set-Content (Join-Path $f.payload 'package.json');Reject {Install-SRBugfix $f.root $f.payload};Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Wrong profile package installed'}}
Test 'RebalanceOptionalPackageId' {$f=Fixture 'SRRebalance';$p=Read-SRJson (Join-Path $f.payload 'package.json');$p.PSObject.Properties.Remove('id');$p|ConvertTo-Json -Depth 10|Set-Content (Join-Path $f.payload 'package.json');Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root;Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Package without optional id failed uninstall'}
Test 'RebalanceForeignLoadersAndInertEmptyFolders' {foreach($name in @('winhttp.dll','doorstop_config.ini')){$f=Fixture 'SRRebalance';[IO.File]::WriteAllText((Join-Path $f.root $name),'foreign');Reject {Install-SRBugfix $f.root $f.payload};Assert ([IO.File]::ReadAllText((Join-Path $f.root $name)) -eq 'foreign') 'Foreign loader altered'};$f=Fixture 'SRRebalance';foreach($name in @('SRBugfix','SRRebalance')){[IO.Directory]::CreateDirectory((Join-Path $f.root $name))|Out-Null};Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root}
Test 'RebalanceWillNotBypassOtherProfileUnpublishedTransaction' {$f=Fixture 'SRRebalance';$dir=Join-Path $f.root '.SRBugfix-transaction';[IO.Directory]::CreateDirectory($dir)|Out-Null;[IO.File]::WriteAllText((Join-Path $dir 'journal.json.new'),'pending');Reject {Install-SRBugfix $f.root $f.payload};Assert ([IO.File]::ReadAllText((Join-Path $dir 'journal.json.new')) -eq 'pending') 'Other transaction changed';Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Installed across pending transaction'}
Test 'UnknownProfileRefused' {Reject {. $SupportPath -ModId 'Unknown'}}
. $SupportPath
$script:ExpectedGame=@{'Star Renegades.exe'='';'Star Renegades_Data/Managed/Assembly-CSharp.dll'='';'Star Renegades_Data/data.unity3d'=''}
$script:SkipProcessForFixtures=$true
Test 'BugfixAllowsKeptRebalanceLogAfterSwitch' {$f=Fixture;$dir=Join-Path $f.root 'SRRebalance';[IO.Directory]::CreateDirectory($dir)|Out-Null;[IO.File]::WriteAllText((Join-Path $dir 'rebalance.log'),'kept log');Install-SRBugfix $f.root $f.payload;Uninstall-SRBugfix $f.root;Assert ([IO.File]::ReadAllText((Join-Path $dir 'rebalance.log')) -eq 'kept log') 'Rebalance log changed'}
Test 'BugfixRejectsUnknownPackageId' {$f=Fixture;$p=Read-SRJson (Join-Path $f.payload 'package.json');$p|Add-Member NoteProperty id 'Unknown';$p|ConvertTo-Json -Depth 10|Set-Content (Join-Path $f.payload 'package.json');Reject {Install-SRBugfix $f.root $f.payload};Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Unknown package installed'}
Test 'ProfilesSerializeOnSameGamePath' {$f=Fixture;$marker=Join-Path $base 'concurrent-action.txt';$supportLiteral=([IO.Path]::GetFullPath($SupportPath)).Replace("'","''");$rootLiteral=$f.root.Replace("'","''");$markerLiteral=$marker.Replace("'","''");$command=". '$supportLiteral' -ModId SRRebalance; try { Invoke-SRLocked '$rootLiteral' { [IO.File]::WriteAllText('$markerLiteral','ran') }; exit 0 } catch { exit 42 }";$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($command));Invoke-SRLocked $f.root {& powershell.exe -NoProfile -ExecutionPolicy Bypass -EncodedCommand $encoded;Assert ($LASTEXITCODE -eq 42) 'Concurrent Rebalance installer was not refused'};Assert (-not(Test-Path $marker)) 'Concurrent installer entered critical section'}
Test 'EntrypointsInstallAndUninstallSelectedProfile' {
 foreach($profile in @('SRBugfix','SRRebalance')){
  $f=Fixture $profile;$installer=Join-Path $f.payload 'Installer';[IO.Directory]::CreateDirectory($installer)|Out-Null
  foreach($name in @('Support.ps1','Install.ps1','Uninstall.ps1')){[IO.File]::Copy((Join-Path ([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($SupportPath))) $name),(Join-Path $installer $name))}
  # Only this copied fixture package trusts the synthetic game's hashes. Production hashes stay unchanged.
  $hashPairs=@();foreach($path in $script:ExpectedGame.Keys){$hashPairs+="'$path'='$($script:ExpectedGame[$path])'"};[IO.File]::AppendAllText((Join-Path $installer 'Support.ps1'),("`r`n"+'$script:ExpectedGame=@{'+($hashPairs -join ';')+'}'))
  $options=if($profile -eq 'SRRebalance'){@('-ModId','SRRebalance')}else{@()}
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $installer 'Install.ps1') -GameRoot $f.root @options;Assert ($LASTEXITCODE -eq 0) "Install entrypoint failed for $profile";Assert (Test-Path (Join-Path $f.root ($profile+'/receipt.json'))) 'Entrypoint selected wrong receipt'
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $installer 'Uninstall.ps1') -GameRoot $f.root @options;Assert ($LASTEXITCODE -eq 0) "Uninstall entrypoint failed for $profile";Assert (-not(Test-Path (Join-Path $f.root 'winhttp.dll'))) 'Entrypoint retained loader'
 }
}
Write-Host "RESULT $passed passed, $failed failed"
if($failed){exit 1}
